// golden_test.go — T-40: the generated-golden differential driver.
//
// testdata/websitepipeline_pure.golden.json is generated by
// testdiff/goldens/dump_websitepipeline.py from the unmodified
// reference (assadigit/GitCurator @ 98f4fc7, the pinned venv's CPython
// 3.12.15 stdlib) with every clock frozen at 2026-10-17 12:00:00 — no
// per-run facts inside. The Go side replays each section against this
// package's port with the same frozen clock and byte-compares.
//
// THE LAW: goldens are never hand-edited; a divergence is either a Go
// bug (fix the port) or a reference behavior change (regenerate + say
// so in the commit).
package websitepipeline

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
	"time"

	"github.com/assadigit/second-brain-project/internal/handdelivery"
	"github.com/assadigit/second-brain-project/internal/storage"
	"github.com/assadigit/second-brain-project/internal/websitepipeline/decomtable"
)

// golden is the decoded corpus (map[string]any — the same shape the
// generator's canon() writes).
var golden map[string]any

func loadGolden(t *testing.T) map[string]any {
	t.Helper()
	if golden != nil {
		return golden
	}
	data, err := os.ReadFile("testdata/websitepipeline_pure.golden.json")
	if err != nil {
		t.Fatalf("golden file: %v", err)
	}
	var g map[string]any
	if err := json.Unmarshal(data, &g); err != nil {
		t.Fatalf("golden json: %v", err)
	}
	golden = g
	return g
}

func section(t *testing.T, name string) map[string]any {
	t.Helper()
	g := loadGolden(t)
	v, ok := g[name].(map[string]any)
	if !ok {
		t.Fatalf("golden section %q missing or not an object", name)
	}
	return v
}

func sectionList(t *testing.T, name string) []any {
	t.Helper()
	g := loadGolden(t)
	v, ok := g[name].([]any)
	if !ok {
		t.Fatalf("golden section %q missing or not a list", name)
	}
	return v
}

// frozenClock is the generator's clock: 2026-10-17 12:00:00 local.
var frozenClock = time.Date(2026, 10, 17, 12, 0, 0, 0, time.Local)

func withFrozenClock(t *testing.T, fn func()) {
	t.Helper()
	origP, origH := clockNow, handdelivery.Clock
	clockNow = func() time.Time { return frozenClock }
	handdelivery.Clock = func() time.Time { return frozenClock }
	defer func() {
		clockNow = origP
		handdelivery.Clock = origH
	}()
	fn()
}

// gstr reads a golden string field.
func gstr(t *testing.T, m map[string]any, key string) string {
	t.Helper()
	v, ok := m[key].(string)
	if !ok {
		t.Fatalf("golden field %q is not a string: %T", key, m[key])
	}
	return v
}

// gint reads a golden number field.
func gint(t *testing.T, m map[string]any, key string) int {
	t.Helper()
	v, ok := m[key].(float64)
	if !ok {
		t.Fatalf("golden field %q is not a number: %T", key, m[key])
	}
	return int(v)
}

// gbool reads a golden boolean field.
func gbool(t *testing.T, m map[string]any, key string) bool {
	t.Helper()
	v, ok := m[key].(bool)
	if !ok {
		t.Fatalf("golden field %q is not a bool: %T", key, m[key])
	}
	return v
}

// glist reads a golden list field.
func glist(t *testing.T, m map[string]any, key string) []any {
	t.Helper()
	v, ok := m[key].([]any)
	if !ok {
		t.Fatalf("golden field %q is not a list: %T", key, m[key])
	}
	return v
}

// gojson renders a Go value exactly as the generator's canon() would
// (sorted keys, no escaping, indent 2) for byte-comparison.
func gojson(v any) string { return storage.PyDumps(v) }

// cmpGoldenJSON byte-compares a Go value against the golden value
// (both canon-encoded).
func cmpGoldenJSON(t *testing.T, what string, got any, want any) {
	t.Helper()
	g := gojson(normalizeGo(got))
	w := gojson(normalizeGolden(want))
	if g != w {
		t.Fatalf("%s diverges from the reference golden:\n--- go ---\n%s\n--- reference ---\n%s",
			what, g, w)
	}
}

// normalizeGo converts Go shapes into the golden's shape ([]string →
// []any, map[string]string → map[string]any, int → float64...).
func normalizeGo(v any) any {
	switch t := v.(type) {
	case []string:
		// nil reads as the reference's [] (a JSON array, never null)
		out := make([]any, len(t))
		for i, s := range t {
			out[i] = s
		}
		return out
	case map[string]string:
		out := map[string]any{}
		for k, s := range t {
			out[k] = s
		}
		return out
	case map[string]bool:
		out := map[string]any{}
		for k, s := range t {
			out[k] = s
		}
		return out
	case map[string]any:
		out := map[string]any{}
		for k, val := range t {
			out[k] = normalizeGo(val)
		}
		return out
	case []map[string]any:
		out := make([]any, len(t))
		for i, val := range t {
			out[i] = normalizeGo(val)
		}
		return out
	case []any:
		out := make([]any, len(t))
		for i, val := range t {
			out[i] = normalizeGo(val)
		}
		return out
	case int:
		return float64(t)
	}
	return v
}

// normalizeGolden leaves the decoded JSON as-is (numbers are float64).
func normalizeGolden(v any) any { return v }

