// gnote builds the generator's NOTE_TMPL note.
func gnote(t *testing.T, path, src string) string {
	t.Helper()
	note := fmt.Sprintf(`---
source: %q
aliases: []
tags: [design]
category: "Design"
subcategory: "Assets & Resources"
fetch_status: "full"
pricing: "free"
login_required: "no"
date_processed: 2026-10-09
managed_by: "gitcurator"
schema_version: "1"
prompt_version: "web-v2"
---

> [!info] Managed by GitCurator — machine-written note.

# Test Site

> **TL;DR:** A test page.

## Best used for
Testing.

## Similar tools
—

---
*Source: [%s](%s)*
`, src, src, src)
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(note), 0o644); err != nil {
		t.Fatal(err)
	}
	return note
}

// gwriteNote writes the generator's write_note shape into a vault.
func gwriteNote(t *testing.T, vault, rel, src, tags, managed, fetch, body string) string {
	t.Helper()
	path := filepath.Join(vault, filepath.FromSlash(rel))
	note := fmt.Sprintf(`---
source: %q
aliases: []
tags: %s
category: "Design"
subcategory: "Assets & Resources"
fetch_status: %q
pricing: "free"
login_required: "no"
date_processed: 2026-10-09
managed_by: %q
schema_version: "1"
prompt_version: "web-v2"
---

> [!info] Managed by GitCurator — machine-written note.

# Test Site

%s

---
*Source: [%s](%s)*
`, src, tags, fetch, managed, body, src, src)
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(note), 0o644); err != nil {
		t.Fatal(err)
	}
	return path
}

// gtable builds the generator's TABLE_TMPL table file.
func gtable(t *testing.T, path string, rows []string) {
	t.Helper()
	content := "# Review Master Table — decommission or approve\n\n> legend line\n\n" +
		"| # | Date | URL | Domain | Source | Status | Notes |\n" +
		"|---|------|-----|--------|--------|--------|-------|\n" +
		strings.Join(rows, "\n") + "\n"
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
}

func readFileT(t *testing.T, path string) string {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	return string(data)
}

func listDirT(t *testing.T, path string) []string {
	t.Helper()
	entries, err := os.ReadDir(path)
	if err != nil {
		t.Fatalf("list %s: %v", path, err)
	}
	var names []string
	for _, e := range entries {
		names = append(names, e.Name())
	}
	sort.Strings(names)
	return names
}

// --- 1. the constants -----------------------------------------------------

func TestGoldenConstants(t *testing.T) {
	g := section(t, "constants")
	cmp := func(name, got string) {
		if got != gstr(t, g, name) {
			t.Errorf("constant %s: got %q want %q", name, got, gstr(t, g, name))
		}
	}
	cmp("WEBSITE_PROMPT_VERSION", WebsitePromptVersion)
	cmp("REVIEW_FOLDER", ReviewFolder)
	cmp("DECOMMISSION_TABLE", DecommissionTable)
	cmp("BANISH_EMOJI", decomtable.BanishEmoji)
	cmp("BANISH_TALLY_PREFIX", BanishTallyPrefix)
	cmp("BANISH_REASON_PREFIX", BanishReasonPrefix)
	cmp("BANISH_GATE_PREFIX", BanishGatePrefix)
	cmp("BANISH_GATE_ENDPOINT", BanishGateEndpoint)
	cmp("TRASH_MARKER", TrashMarker)
	cmp("TRASH_GESTURE", TrashGesture)
	cmp("HAND_DOOR_HINT", HandDoorHint)
	cmp("SITE_LINKS_HEADING", SiteLinksHeading)
	cmp("HAND_FOLDER_NAME", handdelivery.HandFolderName)
	cmp("QUEUE_FILENAME", handdelivery.QueueFilename)
	cmp("README_FILENAME", handdelivery.ReadmeFilename)
	cmp("BODY_TAG_STOPS", BodyTagStops)
	cmp("CANONICAL_HEADER", decomtable.CanonicalHeader)
	cmp("CANONICAL_SEPARATOR", decomtable.CanonicalSeparator)
	if gint(t, g, "FETCH_TIMEOUT_S") != int(FetchTimeoutS) ||
		gint(t, g, "FETCH_MAX_BYTES") != FetchMaxBytes ||
		gint(t, g, "DOMAIN_DELAY_S") != int(DomainDelayS) ||
		gint(t, g, "CLASSIFY_RETRIES") != ClassifyRetries ||
		gint(t, g, "LLM_EXCERPT_CHARS") != LLMExcerptChars ||
		gint(t, g, "MIN_TEXT_FOR_ANALYSIS") != MinTextForAnalysis ||
		gint(t, g, "TABLE_HEADER_CELLS") != decomtable.TableHeaderCells {
		t.Error("a numeric constant diverges from the reference")
	}
	if LowConfidence != gstr(t, g, "LOW_CONFIDENCE") {
		t.Error("LOW_CONFIDENCE diverges")
	}
	cmpLists := func(name string, got []string) {
		cmpGoldenJSON(t, name, got, glist(t, g, name))
	}
	cmpLists("DEAD_MARKERS", decomtable.DeadMarkers)
	cmpLists("REVIVE_MARKERS", decomtable.ReviveMarkers)
	cmpLists("REVIEWED_MARKERS", decomtable.ReviewedMarkers)
	cmpLists("BANISH_WORDS", decomtable.BanishWords)
	cmpLists("BANISH_KEYS", decomtable.BanishKeys)
	cmpLists("TRASH_FOLDER_NAMES", TrashFolderNames)
	cmpLists("HAND_MARKERS", handdelivery.HandMarkers)
	cmpLists("WALL_MARKERS", handdelivery.WallMarkers)
	if BanishQuarantineRelpath != gstr(t, g, "BANISH_QUARANTINE_RELPATH") {
		t.Error("BANISH_QUARANTINE_RELPATH diverges")
	}
}

// --- 2/3. the note builders -------------------------------------------------

func TestGoldenBuildWebsiteNote(t *testing.T) {
	g := section(t, "build_website_note")
	withFrozenClock(t, func() {
		for name, c := range websiteNoteCases() {
			want, ok := g[name].(map[string]any)
			if !ok {
				t.Fatalf("golden case %q missing", name)
			}
			var tags []string
			if c.tags != nil {
				tags = c.tags
			}
			got := BuildWebsiteNote(c.url, c.analysis, c.category, c.subcategory, c.fetchStatus, tags)
			fm, body := splitNote(got)
			if fm != gstr(t, want, "frontmatter") {
				t.Errorf("%s frontmatter diverges:\n--- go ---\n%s\n--- reference ---\n%s",
					name, fm, gstr(t, want, "frontmatter"))
			}
			if body != gstr(t, want, "body") {
				t.Errorf("%s body diverges:\n--- go ---\n%q\n--- reference ---\n%q",
					name, body, gstr(t, want, "body"))
			}
		}
	})
}

func TestGoldenBuildReviewNote(t *testing.T) {
	g := section(t, "build_review_note")
	withFrozenClock(t, func() {
		for name, c := range reviewNoteCases() {
			want, ok := g[name].(map[string]any)
			if !ok {
				t.Fatalf("golden case %q missing", name)
			}
			got := BuildReviewNote(c.url, c.fetchStatus, c.reason, c.title, c.tags)
			fm, body := splitNote(got)
			if fm != gstr(t, want, "frontmatter") {
				t.Errorf("%s frontmatter diverges:\n--- go ---\n%s\n--- reference ---\n%s",
					name, fm, gstr(t, want, "frontmatter"))
			}
			if body != gstr(t, want, "body") {
				t.Errorf("%s body diverges:\n--- go ---\n%q\n--- reference ---\n%q",
					name, body, gstr(t, want, "body"))
			}
		}
	})
}

func splitNote(note string) (fm, body string) {
	if strings.HasPrefix(note, "---\n") {
		rest := note[4:]
		if i := strings.Index(rest, "\n---\n"); i >= 0 {
			return rest[:i], rest[i+len("\n---\n"):]
		}
	}
	return "", note
}

