// --- 4. the site-links battery ----------------------------------------------

func TestGoldenSiteLinks(t *testing.T) {
	g := section(t, "parse_site_links_list")
	cmpGoldenJSON(t, "parse_site_links_list.flow",
		ParseSiteLinksList("[https://a.example/, https://b.example/]"), g["flow"])
	cmpGoldenJSON(t, "parse_site_links_list.quoted",
		ParseSiteLinksList(`["https://a.example/", 'https://b.example/']`), g["quoted"])
	cmpGoldenJSON(t, "parse_site_links_list.empty",
		ParseSiteLinksList("[]"), g["empty"])
	cmpGoldenJSON(t, "parse_site_links_list.blank",
		ParseSiteLinksList(""), g["blank"])
	cmpGoldenJSON(t, "parse_site_links_list.single",
		ParseSiteLinksList("[https://one.example/]"), g["single"])
	cmpGoldenJSON(t, "parse_site_links_list.spaces",
		ParseSiteLinksList("[ https://a.example/ , https://b.example/ ]"), g["spaces"])
	if got := FmtSiteLinksList([]string{"https://a.example/", "https://b.example/"}); got != gstr(t, loadGolden(t), "fmt_site_links_list") {
		t.Errorf("fmt_site_links_list: %q", got)
	}

	sg := section(t, "add_site_links_to_note")
	withFrozenClock(t, func() {
		tmp := t.TempDir()
		fresh := filepath.Join(tmp, "sl", "fresh.md")
		gnote(t, fresh, "https://site.example/")
		rep := AddSiteLinksToNote(fresh, []string{"https://site.example/page2"}, nil)
		cmpSiteLinks(t, "fresh", rep, readFileT(t, fresh), sg["fresh"])

		replace := filepath.Join(tmp, "sl", "replace.md")
		if err := os.Rename(fresh, replace); err != nil {
			t.Fatal(err)
		}
		rep = AddSiteLinksToNote(replace, []string{"https://site.example/page3"}, nil)
		cmpSiteLinks(t, "extend", rep, readFileT(t, replace), sg["extend"])

		rep = AddSiteLinksToNote(replace, []string{"https://site.example/page3"}, nil)
		// idempotent: nothing appended
		idem := sg["idempotent"].(map[string]any)["rep"].(map[string]any)
		if rep.Already != gint(t, idem, "already") {
			t.Errorf("idempotent already: got %d", rep.Already)
		}
		if len(rep.Appended) != 0 || rep.Written {
			t.Errorf("idempotent wrote again: %+v", rep)
		}

		rep = AddSiteLinksToNote(replace, []string{"https://site.example/page3", "https://site.example/page4"}, nil)
		if len(rep.Appended) != 1 || rep.Appended[0] != "https://site.example/page4" {
			t.Errorf("one_new_one_old appended: %+v", rep.Appended)
		}

		nosource := filepath.Join(tmp, "sl", "nosource.md")
		os.MkdirAll(filepath.Dir(nosource), 0o755)
		os.WriteFile(nosource, []byte("---\naliases: []\ntags: []\n---\n\nBody only.\n"), 0o644)
		rep = AddSiteLinksToNote(nosource, []string{"https://nosrc.example/x"}, nil)
		cmpSiteLinks(t, "no_source_line", rep, readFileT(t, nosource), sg["no_source_line"])

		nofm := filepath.Join(tmp, "sl", "nofm.md")
		os.WriteFile(nofm, []byte("Just a body, no frontmatter at all.\n"), 0o644)
		rep = AddSiteLinksToNote(nofm, []string{"https://nofm.example/x"}, nil)
		cmpSiteLinks(t, "no_frontmatter", rep, readFileT(t, nofm), sg["no_frontmatter"])

		nofooter := filepath.Join(tmp, "sl", "nofooter.md")
		os.WriteFile(nofooter, []byte("---\nsource: \"https://nf.example/\"\n---\n\n# No Footer\n\nBody text.\n"), 0o644)
		rep = AddSiteLinksToNote(nofooter, []string{"https://nf.example/x"}, nil)
		cmpSiteLinks(t, "no_footer", rep, readFileT(t, nofooter), sg["no_footer"])

		nls := section(t, "note_lists_site_link")
		if got := NoteListsSiteLink(replace, "https://site.example/page3"); got != gbool(t, nls, "present") {
			t.Errorf("note_lists_site_link.present: %v", got)
		}
		if got := NoteListsSiteLink(replace, "https://site.example/other"); got != gbool(t, nls, "absent") {
			t.Errorf("note_lists_site_link.absent: %v", got)
		}
		if got := NoteListsSiteLink(filepath.Join(tmp, "sl", "none.md"), "https://x.example/"); got != gbool(t, nls, "missing_file") {
			t.Errorf("note_lists_site_link.missing_file: %v", got)
		}

		rnp := section(t, "read_note_placement")
		cat, sub, status := NotePlacement(replace)
		want := rnp["full"].([]any)
		if cat != want[0] || sub != want[1] || status != want[2] {
			t.Errorf("read_note_placement.full: got (%q,%q,%q) want %v", cat, sub, status, want)
		}
	})
}

func cmpSiteLinks(t *testing.T, name string, rep SiteLinksResult, file string, wantAny any) {
	t.Helper()
	want, ok := wantAny.(map[string]any)
	if !ok {
		t.Fatalf("golden site-links case %q missing", name)
	}
	r, ok := want["rep"].(map[string]any)
	if !ok {
		t.Fatalf("golden site-links case %q has no rep", name)
	}
	appended, _ := r["appended"].([]any)
	cmpGoldenJSON(t, name+".appended", rep.Appended, appended)
	if rep.Already != gint(t, r, "already") {
		t.Errorf("%s.already: got %d want %d", name, rep.Already, gint(t, r, "already"))
	}
	if rep.Written != gbool(t, r, "written") {
		t.Errorf("%s.written: got %v want %v", name, rep.Written, gbool(t, r, "written"))
	}
	if f, ok := want["file"].(string); ok && file != f {
		t.Errorf("%s file diverges:\n--- go ---\n%q\n--- reference ---\n%q", name, file, f)
	}
}

// --- 5. the table cell + status predicates ----------------------------------

func TestGoldenTableCell(t *testing.T) {
	g := section(t, "table_cell")
	for name, want := range g {
		var limit int
		switch name {
		case "long", "unicode":
			limit = 96
		case "over_limit_short":
			limit = 10
		default:
			limit = 96
		}
		got := decomtable.TableCell(inputForCell(name), limit)
		if got != want.(string) {
			t.Errorf("table_cell.%s: got %q want %q", name, got, want.(string))
		}
	}
}

func inputForCell(name string) string {
	switch name {
	case "plain":
		return "plain text"
	case "pipes":
		return "a|b|c"
	case "newlines":
		return "line1\nline2\r\nline3"
	case "collapse":
		return "  spaced    out\t text  "
	case "long":
		return strings.Repeat("x", 200)
	case "exact_limit":
		return strings.Repeat("y", 96)
	case "over_limit_short":
		return strings.Repeat("z", 11)
	case "unicode":
		return strings.Repeat("é", 150)
	}
	return ""
}

func TestGoldenStatusPredicates(t *testing.T) {
	for _, r := range sectionList(t, "status_predicates") {
		m := r.(map[string]any)
		s := gstr(t, m, "status")
		check := func(name string, got, want bool) {
			if got != want {
				t.Errorf("status %q: %s: got %v want %v", s, name, got, want)
			}
		}
		check("dead", decomtable.StatusIsDead(s), gbool(t, m, "dead"))
		check("revived", decomtable.StatusIsRevived(s), gbool(t, m, "revived"))
		check("banished", decomtable.StatusIsBanished(s), gbool(t, m, "banished"))
		check("reviewed", decomtable.StatusIsReviewed(s), gbool(t, m, "reviewed"))
		check("waiting", StatusIsWaiting(s), gbool(t, m, "waiting"))
		check("terminal", decomtable.StatusIsTerminal(s), gbool(t, m, "terminal"))
		check("hand", handdelivery.StatusIsHand(s), gbool(t, m, "hand"))
	}
	g := section(t, "is_walled_reason")
	for reason, want := range g {
		if got := handdelivery.IsWalledReason(reason); got != want.(bool) {
			t.Errorf("is_walled_reason(%q): got %v want %v", reason, got, want.(bool))
		}
	}
}

// --- 7. parse_decommission_rows -----------------------------------------------

func TestGoldenParseDecommissionRows(t *testing.T) {
	g := section(t, "parse_decommission_rows")
	tmp := t.TempDir()
	for name, rows := range decomRowCases() {
		path := filepath.Join(tmp, "table_"+name+".md")
		gtable(t, path, rows)
		got := ParseDecommissionRows(pySplitLines(readFileT(t, path)))
		cmpGoldenJSON(t, "parse_decommission_rows."+name, rowsView(got), g[name])
	}
}

func rowsView(rows []decomtable.Row) []map[string]any {
	out := make([]map[string]any, 0, len(rows))
	for _, r := range rows {
		out = append(out, map[string]any{
			"url": r.URL, "status": r.Status, "icon": r.Icon,
			"notes": r.Notes, "line": float64(r.Line),
		})
	}
	return out
}

func decomRowCases() map[string][]string {
	return map[string][]string{
		"canonical": {
			"| - | 2026-10-01 | https://a.example/x | a.example | waiting | unreviewed | |",
			"| 🪦 | 2026-10-01 | https://b.example/y | b.example | waiting |  | note b |",
			"| - | 2026-10-01 | https://c.example/z | c.example | waiting | ✅ | |",
		},
		"trimmed_four_col": {
			"| - | 2026-10-01 | https://a.example/x | a.example |",
			"| 💀 | 2026-10-01 | https://b.example/y | b.example |",
		},
		"icon_carries_verdict": {
			"| 🖐 | 2026-10-01 | https://hand.example/x | hand.example | waiting | unreviewed | |",
			"| - | 2026-10-01 | https://plain.example/x | plain.example | waiting | — | |",
		},
		"hand_made_url_cell": {
			"| - | 2026-10-01 | not-a-url | d.example | waiting | unreviewed | |",
			"| - | 2026-10-01 | text | https://early.example/u | waiting | unreviewed | |",
			"| - | 2026-10-01 | https://late.example/u | text | text | unreviewed | |",
		},
		"short_rows": {
			"| - | 2026-10-01 | https://s.example/u |",
			"|notpipe| 2026-10-01 | https://np.example/u | x |",
			"|   |   |   |   |",
		},
		"separator_only": {
			"|---|------|-----|--------|--------|--------|-------|",
		},
	}
}

// --- 8. the frontmatter/body-tag parses ---------------------------------------

func TestGoldenFrontmatterParses(t *testing.T) {
	tmp := t.TempDir()
	rfm := section(t, "parse_review_frontmatter")
	for name, text := range reviewFMCaseTexts() {
		p := filepath.Join(tmp, "fm", name+".md")
		os.MkdirAll(filepath.Dir(p), 0o755)
		os.WriteFile(p, []byte(text), 0o644)
		fm := ParseReviewFrontmatter(p)
		want := rfm[name]
		if want == nil {
			if fm != nil {
				t.Errorf("parse_review_frontmatter.%s: expected nil, got %+v", name, fm)
			}
			continue
		}
		wm := want.(map[string]any)
		if fm == nil {
			t.Errorf("parse_review_frontmatter.%s: expected %+v, got nil", name, wm)
			continue
		}
		// the reference dict omits absent keys — nil reads as ""
		nstr := func(key string) string {
			if v, ok := wm[key].(string); ok {
				return v
			}
			return ""
		}
		if fm.Source != nstr("source") || fm.FetchStatus != nstr("fetch_status") ||
			fm.ManagedBy != nstr("managed_by") {
			t.Errorf("parse_review_frontmatter.%s: got %+v want %v", name, fm, wm)
		}
	}

	bfm := section(t, "parse_banish_frontmatter")
	for name, text := range banishFMCaseTexts() {
		p := filepath.Join(tmp, "bfm", name+".md")
		os.MkdirAll(filepath.Dir(p), 0o755)
		os.WriteFile(p, []byte(text), 0o644)
		fm := ParseBanishFrontmatter(p)
		want := bfm[name]
		if want == nil {
			if fm != nil {
				t.Errorf("parse_banish_frontmatter.%s: expected nil", name)
			}
			continue
		}
		wm := want.(map[string]any)
		if fm == nil {
			t.Errorf("parse_banish_frontmatter.%s: expected %+v, got nil", name, wm)
			continue
		}
		if fm.Source != gstr(t, wm, "source") {
			t.Errorf("parse_banish_frontmatter.%s.source", name)
		}
		cmpGoldenJSON(t, "parse_banish_frontmatter."+name+".tags", fm.Tags, glist(t, wm, "tags"))
		marked, marker := NoteReadsBanished(fm)
		rb, _ := wm["reads_banished"].([]any)
		if len(rb) != 2 {
			t.Fatalf("parse_banish_frontmatter.%s: reads_banished shape", name)
		}
		wantMarked, _ := rb[0].(bool)
		wantMarker, _ := rb[1].(string)
		if marked != wantMarked || marker != wantMarker {
			t.Errorf("parse_banish_frontmatter.%s.reads_banished: got (%v, %q) want (%v, %q)",
				name, marked, marker, wantMarked, wantMarker)
		}
	}

	btag := section(t, "note_body_banish_tag")
	for name, text := range bodyCaseTexts() {
		p := filepath.Join(tmp, "btag", name+".md")
		os.MkdirAll(filepath.Dir(p), 0o755)
		os.WriteFile(p, []byte(text), 0o644)
		got := NoteBodyBanishTag(p)
		if got != gstr(t, btag, name) {
			t.Errorf("note_body_banish_tag.%s: got %q want %q", name, got, gstr(t, btag, name))
		}
	}
}

