func TestGoldenIsTrashFolder(t *testing.T) {
	g := section(t, "is_trash_folder")
	for _, c := range []struct{ name, input string }{
		{"trash", "Trash"}, {"lower", "trash"}, {"sub", "Trash/sub"},
		{"deep", "Some/Trash"}, {"dot", ".trash"}, {"empty", ""},
		{"dot_only", "."}, {"windows", `Trash\sub`},
	} {
		want := gbool(t, g, c.name)
		if got := IsTrashFolder(c.input); got != want {
			t.Errorf("is_trash_folder(%q): got %v want %v", c.input, got, want)
		}
	}
}
